    struct sock *new_sk;
    struct sctp6_sock *new_sp;
    struct sctp_sock *new_sctp;

    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern);
    if (!new_sk)
        return NULL;

    sctp_sk(new_sk) = *sctp_sk(sk);
    new_sctp = sctp_sk(new_sk);
    new_sctp->asoc = *asoc;

    new_sp = (struct sctp6_sock *)new_sk;
    new_sp->sctp6_ipv6_only = true;

    if (sctp_init_sock(new_sk)) {
        sk_free(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_create_new_sock(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    struct sctcp *new_sp;

    new_sk = sock_alloc();
    if (!new_sk)
        return NULL;

    sock_init_data(new_sk, sk->sk_prot, kern);

    new_sp = sctp_sk(new_sk);
    if (!new_sp) {
        sock_release(new_sk);
        return NULL;
    }

    new_sp->asoc = *asoc;
    new_sk->sk_family = AF_INET6;

    if (sk->sk_prot->init && sk->sk_prot->init(new_sk) < 0) {
        sock_release(new_sk);
        return NULL;
    }

    return new_sk;
}

