struct sock *sctp6_create_new_sock(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    int ret;

    new_sk = sk_clone(sk, GFP_KERNEL);
    if (!new_sk)
        return NULL;

    sctp_sk(new_sk) = sctp_sk(sk);
    sctp_association_copy(new_sk, asoc);

    ret = sctp6_init_sock(new_sk);
    if (ret < 0) {
        sock_release(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sp;
    int err;

    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern);
    if (!new_sk)
        return NULL;

    new_sk->sk_family = AF_INET6;
    new_sk->sk_type = sk->sk_type;
    new_sk->sk_protocol = sk->sk_protocol;

    new_sp = (struct sctp6_sock *)new_sk;
    new_sp->asoc = asoc;

    err = sctp_sock_init(new_sk, sk);
    if (err) {
        sk_free(new_sk);
        return NULL;
    }

    sctp6_init_sock(new_sp, sk);

    return new_sk;
}
